import { createServerFn } from "@tanstack/react-start";

import type { Bed, Unit, UnitRoom, UpcomingStay } from "@/lib/ops-store";

/* eslint-disable @typescript-eslint/no-explicit-any */

/**
 * Homes: physical inventory (units -> rooms -> beds).
 *
 * The tables mirror the ops-store types one-for-one, so everything here is a
 * name translation: snake_case in Postgres, camelCase in TypeScript. Nothing
 * outside this file sees a database column name.
 */

/**
 * units / rooms / beds / import_batches are not in the generated Database type
 * yet (that file is regenerated by Lovable, so it is not edited by hand).
 * Cast to any until it catches up.
 */
/** the service-role client - only after the admin session is checked (adminDb) */
async function admin(): Promise<any> {
  const { adminDb } = await import("@/lib/admin-session.server");
  return adminDb();
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const isUuid = (v?: string) => !!v && UUID.test(v);

/* ---------------- row -> type ---------------- */

function toBed(row: any): Bed {
  return {
    id: row.id,
    label: row.label,
    status: row.status,
    residentId: row.resident_id ?? undefined,
    residentName: row.resident_name ?? undefined,
    studentId: row.student_id ?? undefined,
    university: row.university ?? undefined,
    nationality: row.nationality ?? undefined,
    gender: row.gender ?? undefined,
    tenancyStart: row.tenancy_start ?? undefined,
    tenancyEnd: row.tenancy_end ?? undefined,
    rent: row.rent ?? undefined,
    holdFor: row.hold_for ?? undefined,
    holdUntil: row.hold_until ?? undefined,
    enquiryId: row.enquiry_id ?? undefined,
    upcoming: row.upcoming?.length ? row.upcoming : undefined,
  };
}

/**
 * Every claim on the units' beds, with dates - SQL placement_claims
 * (20261014100000_one_placement.sql), the same list place_stay checks a stay
 * against. Null: every unit. Screens read this, never their own copy of it.
 */
export async function placementClaims(supabase: any, unitIds: string[] | null) {
  const { data, error } = await supabase.rpc("placement_claims", { p_units: unitIds });
  if (error) throw new Error(rpcError(error));
  return (data ?? []) as {
    bed_id: string;
    room_id: string;
    unit_id: string;
    enquiry_id: string | null;
    resident_id: string | null;
    who: string;
    gender: string;
    starts: string | null;
    ends: string | null;
    source: "resident" | "hold" | "move" | "manual" | "tenancy";
  }[];
}

/**
 * The stays to come on each bed while somebody else is its resident (9 Oct
 * 2026), from placementClaims - nothing on the bed row stores them:
 *   Reserved   a booking's hold before the booking fee is in, or a room held
 *              for a resident's Update Tenancy change (14 Oct 2026)
 *   Booked     a paid tenancy placed on the bed whose resident is not the
 *              bed's, has not ended, and is not living in another bed already
 * Earliest first, so a bed can have more than one.
 */
async function attachUpcoming(supabase: any, beds: any[], unitIds: string[]) {
  if (!beds.length) return beds;
  const bedIds = new Set(beds.map((b) => String(b.id)));
  const claims = (await placementClaims(supabase, unitIds)).filter(
    (c) =>
      bedIds.has(String(c.bed_id)) &&
      (c.source === "hold" || c.source === "move" || c.source === "tenancy"),
  );
  const enquiryIds = [...new Set(claims.map((c) => c.enquiry_id).filter(Boolean))] as string[];
  const residentIds = [...new Set(claims.map((c) => c.resident_id).filter(Boolean))] as string[];
  const [{ data: enquiries }, { data: residents }, { data: invoices }] = await Promise.all([
    enquiryIds.length
      ? supabase.from("enquiries").select("id, reference, status, full_name, gender, university, move_in, move_out, monthly_rent, resident_id").in("id", enquiryIds)
      : { data: [] },
    residentIds.length
      ? supabase.from("residents").select("id, full_name, gender, university, status, resident_code, quickbooks_id, enquiry_id").in("id", residentIds)
      : { data: [] },
    enquiryIds.length
      ? supabase.from("invoices").select("enquiry_id, monthly_rent, created_at").in("enquiry_id", enquiryIds).neq("status", "void").order("created_at", { ascending: false })
      : { data: [] },
  ]);
  const enq = new Map(((enquiries ?? []) as any[]).map((e) => [e.id, e]));
  const res = new Map(((residents ?? []) as any[]).map((r) => [r.id, r]));
  const rentOf = (id?: string | null) =>
    Number(
      ((invoices ?? []) as any[]).find((i) => i.enquiry_id === id)?.monthly_rent ||
        enq.get(id ?? "")?.monthly_rent ||
        0,
    ) || undefined;

  return beds.map((b) => {
    const list: UpcomingStay[] = [];
    for (const c of claims) {
      if (c.bed_id !== b.id) continue;
      if (c.source === "hold") {
        // a booking's unpaid hold
        const e = enq.get(c.enquiry_id);
        if (!e) continue;
        list.push({
          enquiryId: e.id,
          reference: e.reference || undefined,
          // made a resident at the booking fee: their page finds the room by this (13 Oct 2026)
          ...(e.resident_id ? { residentId: e.resident_id } : {}),
          name: String(e.full_name ?? ""),
          gender: e.gender || undefined,
          university: e.university || undefined,
          start: c.starts || undefined,
          end: c.ends || undefined,
          rent: rentOf(e.id),
          // Reserved until the booking fee is in, then Booked - the booking's own stage says which (docs/MISTAKES-TO-AVOID.md 7)
          status: e.status === "booked" ? "booked" : "reserved",
        });
        continue;
      }
      const r = res.get(c.resident_id);
      if (!r) continue;
      // a resident's own bed held on for their extension is still theirs - not a second person
      if (c.source === "move" && c.resident_id === b.resident_id) continue;
      const te = enq.get(c.enquiry_id ?? "");
      list.push({
        ...(c.enquiry_id ? { enquiryId: c.enquiry_id } : {}),
        reference: te?.reference || undefined,
        residentId: r.id,
        name: String(r.full_name || te?.full_name || ""),
        code: String(r.resident_code || r.quickbooks_id || "") || undefined,
        gender: r.gender || undefined,
        university: r.university || te?.university || undefined,
        start: c.starts || undefined,
        end: c.ends || undefined,
        rent: rentOf(c.enquiry_id),
        // a room held for an Update Tenancy change is Reserved until it takes effect (14 Oct 2026)
        status: c.source === "move" ? "reserved" : "booked",
      });
    }
    list.sort((x, y) => String(x.start ?? "").localeCompare(String(y.start ?? "")));
    return list.length ? { ...b, upcoming: list } : b;
  });
}

function toRoom(row: any, beds: any[]): UnitRoom {
  return {
    id: row.id,
    letter: row.letter,
    roomTypeCode: row.room_type_code ?? "",
    occupancy: row.occupancy === "twin" || row.occupancy === "unit" ? row.occupancy : "single",
    rent: Number(row.rent ?? 0),
    beds: beds
      .filter((b) => b.room_id === row.id)
      .sort(
        (a, b) =>
          (a.sort_order ?? 0) - (b.sort_order ?? 0) ||
          String(a.label).localeCompare(String(b.label)),
      )
      .map(toBed),
  };
}

function toUnit(row: any, rooms: any[], beds: any[]): Unit {
  const res = row.residences ?? {};
  return {
    id: row.id,
    code: row.code ?? "",
    residenceId: row.residence_id,
    residenceName: res.name ?? "",
    residenceSlug: res.slug ?? "",
    unitNo: row.unit_no ?? "",
    block: row.block ?? "",
    floor: row.floor ?? "",
    unitType: row.unit_type ?? "",
    gender: row.gender ?? "",
    wholeUnit: !!row.whole_unit,
    wholeUnitRent: Number(row.whole_unit_rent ?? 0),
    notes: row.notes ?? "",
    deactivatedAt: row.deactivated_at ?? "",
    deactivationReason: row.deactivation_reason ?? "",
    rooms: rooms
      .filter((r) => r.unit_id === row.id)
      .sort(
        (a, b) =>
          (a.sort_order ?? 0) - (b.sort_order ?? 0) ||
          String(a.letter).localeCompare(String(b.letter)),
      )
      .map((r) => toRoom(r, beds)),
  };
}

/* ---------------- read ---------------- */

export const listUnits = createServerFn({ method: "GET" }).handler(async (): Promise<Unit[]> => {
  const supabase = await admin();
  const { data: units, error } = await supabase
    .from("units")
    .select("*, residences(name, slug)")
    .order("code");
  if (error) throw new Error(error.message);
  if (!units?.length) return [];

  const unitIds = units.map((u: any) => u.id);
  const { data: rooms, error: roomErr } = await supabase
    .from("rooms")
    .select("*")
    .in("unit_id", unitIds);
  if (roomErr) throw new Error(roomErr.message);

  const roomIds = (rooms ?? []).map((r: any) => r.id);
  const beds = roomIds.length
    ? await attachUpcoming(
        supabase,
        (await supabase.from("beds").select("*").in("room_id", roomIds)).data ?? [],
        unitIds,
      )
    : [];

  return units.map((u: any) => toUnit(u, rooms ?? [], beds));
});

/* ---------------- write ---------------- */

/**
 * Upsert a whole unit with its rooms and beds.
 *
 * Rooms match on (unit_id, letter) and beds on (room_id, label), so saving an
 * existing unit keeps every id stable and preserves bed status. Anything the
 * payload no longer contains is removed.
 */
export const saveUnitRow = createServerFn({ method: "POST" })
  .inputValidator((data: { unit: Unit; importBatchId?: string }) => data)
  .handler(async ({ data }): Promise<Unit> => saveUnitWith(await admin(), data));

/**
 * saveUnitRow's body - handed the client, so the database tests can run it too.
 *
 * It saves the unit, its rooms and its beds' labels - never who is in a bed
 * (14 Oct 2026). The page sends its own copy of the beds, which can be an hour
 * old: written back, it put a moved or newly booked resident back where they
 * were. Who is in a bed is written only by the placement functions.
 */
export async function saveUnitWith(
  supabase: any,
  data: { unit: Unit; importBatchId?: string },
): Promise<Unit> {
  {
    const { unit, importBatchId } = data;

    // a unit is let whole (one "Unit" bed) or by room - never both. Every screen
    // keeps to this, and this refuses anything that did not
    const slots = unit.rooms.filter((r) => r.letter.toLowerCase() === "unit");
    if (slots.length && slots.length !== unit.rooms.length) {
      throw new Error(`${unit.unitNo}: a unit is let either whole or by room, not both`);
    }
    // and let whole only when Website gives its unit type a whole-unit rate (11 Oct 2026)
    if (slots.length) {
      const { data: resRow } = await supabase.from("residences").select("unit_rates").eq("id", unit.residenceId).maybeSingle();
      const { wholeUnitOffered } = await import("@/lib/room-offer");
      const taken = slots.some((r) => r.beds.some((b) => b.residentId || b.enquiryId || b.status !== "vacant"));
      if (!taken && !wholeUnitOffered(resRow as any, unit.unitType ?? "")) {
        throw new Error(`${unit.unitNo}: no whole-unit rate in Website for ${unit.unitType || "this unit type"}`);
      }
    }

    /*
     * The code this unit is known by - U001, U002, and no dash, the way the
     * master list writes it.
     *
     * ONE sequence across every residence, not one per residence. The Arc ends
     * at U075 and Solstice carries straight on at U076, so the next new unit of
     * either is U087. Per-residence letters were tidier to read, but these
     * codes are already printed on invoices that have gone out, and an invoice
     * quoting U063 has to lead back to a unit called U063.
     *
     * Worked out here rather than in the page, because only here is the
     * residence certain: Add unit mints a draft before anybody has picked one,
     * and the bulk upload has no say in it at all.
     *
     * A unit that already exists keeps the code it has. Codes are read by
     * people and printed on lists, so one must never move under a unit that is
     * merely being edited.
     *
     * A new one takes the HIGHEST number already given rather than how many
     * units there are. U028 is a deliberate gap - B-13A-01 is deactivated - and
     * counting would hand that number out a second time.
     */
    const found = isUuid(unit.id)
      ? await supabase.from("units").select("code").eq("id", unit.id).maybeSingle()
      : await supabase
          .from("units")
          .select("code")
          .eq("residence_id", unit.residenceId)
          .eq("unit_no", unit.unitNo)
          .maybeSingle();

    let code = String((found.data as any)?.code ?? "").trim();
    if (!code) {
      const { data: res } = await supabase
        .from("residences")
        .select("unit_prefix")
        .eq("id", unit.residenceId)
        .maybeSingle();
      /*
       * Blank means U. It used to fall back to the first letter of the
       * residence's name, which made sense while each had its own letter and
       * is simply wrong now - it would mint T001 for The Arc.
       */
      const prefix = String((res as any)?.unit_prefix ?? "").trim() || "U";
      // every unit, not this residence's: the sequence is shared, and counting
      // within one residence would hand Solstice a number The Arc already has
      const { data: all } = await supabase.from("units").select("code");
      const highest = ((all ?? []) as any[]).reduce((max, r) => {
        const digits = /(\d+)\s*$/.exec(String(r.code ?? ""));
        return digits ? Math.max(max, Number(digits[1])) : max;
      }, 0);
      code = `${prefix}${String(highest + 1).padStart(3, "0")}`;
    }

    const unitRow = {
      residence_id: unit.residenceId,
      code,
      unit_no: unit.unitNo,
      block: unit.block ?? "",
      floor: unit.floor ?? "",
      unit_type: unit.unitType ?? "",
      gender: unit.gender ?? "",
      // whether it is let whole follows from its rooms, so the two cannot disagree
      whole_unit: slots.length > 0,
      whole_unit_rent: unit.wholeUnitRent ?? 0,
      notes: unit.notes ?? "",
      ...(importBatchId ? { import_batch_id: importBatchId } : {}),
    };

    const { data: saved, error } = await supabase
      .from("units")
      .upsert(isUuid(unit.id) ? { id: unit.id, ...unitRow } : unitRow, {
        onConflict: "residence_id,unit_no",
      })
      .select("id")
      .single();
    if (error) throw new Error(error.message);
    const unitId = (saved as any).id as string;

    // rooms
    const roomRows = unit.rooms.map((r, i) => ({
      unit_id: unitId,
      letter: r.letter,
      room_type_code: r.roomTypeCode ?? "",
      occupancy: r.occupancy,
      rent: r.rent ?? 0,
      sort_order: i,
      ...(importBatchId ? { import_batch_id: importBatchId } : {}),
    }));
    const { data: savedRooms, error: roomErr } = roomRows.length
      ? await supabase
          .from("rooms")
          .upsert(roomRows, { onConflict: "unit_id,letter" })
          .select("id, letter")
      : { data: [] as any[], error: null };
    if (roomErr) throw new Error(roomErr.message);

    // beds
    const roomIdByLetter = new Map<string, string>(
      (savedRooms ?? []).map((r: any) => [r.letter as string, r.id as string]),
    );
    const bedRows: any[] = [];
    for (const room of unit.rooms) {
      const roomId = roomIdByLetter.get(room.letter);
      if (!roomId) continue;
      // the label and the order only: a new bed starts vacant, an existing one keeps who is in it
      room.beds.forEach((b, i) => {
        bedRows.push({
          room_id: roomId,
          label: b.label,
          sort_order: i,
          ...(importBatchId ? { import_batch_id: importBatchId } : {}),
        });
      });
    }
    if (bedRows.length) {
      const { error: bedErr } = await supabase
        .from("beds")
        .upsert(bedRows, { onConflict: "room_id,label" });
      if (bedErr) throw new Error(bedErr.message);
    }

    /*
     * A room or bed the page no longer lists goes - unless somebody is placed
     * on it: in it now, holding it, coming to it, or there before (their
     * tenancy names it, and their statement and documents still read it).
     * Checked and deleted in one step under the unit's lock (14 Oct 2026), so a
     * reservation made a moment before is never deleted with its bed.
     */
    {
      const { data: dropped, error: dropErr } = await supabase.rpc("drop_unused_rooms_beds", {
        p_unit: unitId,
        p_rooms: unit.rooms.map((r) => ({ letter: r.letter, labels: r.beds.map((b) => b.label) })),
      });
      if (dropErr) throw new Error(rpcError(dropErr));
      const out = dropped as { ok: boolean; busy?: string[] };
      if (!out?.ok) {
        throw new Error(
          `${unit.unitNo}: ${(out?.busy ?? []).join(", ")} cannot be removed - somebody is placed there, now, later or before. Move them first.`,
        );
      }
    }

    // twin or single follows the room type in Website, whatever was sent
    await syncRoomShapes(supabase, unitId);
    return await readUnit(supabase, unitId);
  }
}

/**
 * Give units the codes the master list gives them (Dani, 12 Oct 2026).
 *
 * The units upload reads each unit's code from the file. Codes move between
 * units at once - B-13A-01 takes U028 from a unit that is itself becoming U035 -
 * so every unit named here first steps aside to a temporary code, then takes
 * its own. A code held by a unit NOT named here is refused, never taken from it.
 */
export const setUnitCodes = createServerFn({ method: "POST" })
  .inputValidator((data: { codes: { unitId: string; code: string }[] }) => data)
  .handler(async ({ data }) => {
    const supabase = await admin();
    const wanted = data.codes.filter((c) => isUuid(c.unitId) && c.code.trim());
    const ids = new Set(wanted.map((c) => c.unitId));
    const codes = wanted.map((c) => c.code.trim());
    const dup = codes.find((c, i) => codes.indexOf(c) !== i);
    if (dup) return { ok: false as const, error: `${dup} is given to two units in the file` };
    const { data: holders } = await supabase.from("units").select("id, code, unit_no").in("code", codes);
    const blocked = ((holders ?? []) as any[]).filter((h) => !ids.has(h.id));
    if (blocked.length) {
      return {
        ok: false as const,
        error: `Already used by units not in the file: ${blocked.map((b) => `${b.code} (${b.unit_no})`).join(", ")}`,
      };
    }
    for (const c of wanted) {
      const { error } = await supabase.from("units").update({ code: `TMP-${c.unitId}` }).eq("id", c.unitId);
      if (error) throw new Error(error.message);
    }
    for (const c of wanted) {
      const { error } = await supabase
        .from("units")
        .update({ code: c.code.trim(), updated_at: new Date().toISOString() })
        .eq("id", c.unitId);
      if (error) throw new Error(error.message);
    }
    return { ok: true as const, changed: wanted.length };
  });

/**
 * Put rooms nobody is in back in line with their room type in Website (11 Oct
 * 2026) - sync_room_shapes in 20261011110000_room_shape_from_website.sql. A
 * database without that migration keeps the rooms as they were.
 */
export async function syncRoomShapes(supabase: any, unitId?: string) {
  const { error } = await supabase.rpc("sync_room_shapes", unitId ? { p_unit: unitId } : {});
  if (error && !notMigrated(error)) throw new Error(error.message);
}

export async function readUnit(supabase: any, unitId: string): Promise<Unit> {
  const { data: row, error } = await supabase
    .from("units")
    .select("*, residences(name, slug)")
    .eq("id", unitId)
    .single();
  if (error) throw new Error(error.message);
  const { data: rooms } = await supabase.from("rooms").select("*").eq("unit_id", unitId);
  const roomIds = (rooms ?? []).map((r: any) => r.id);
  const beds = roomIds.length
    ? await attachUpcoming(
        supabase,
        (await supabase.from("beds").select("*").in("room_id", roomIds)).data ?? [],
        [unitId],
      )
    : [];
  return toUnit(row, rooms ?? [], beds);
}

/**
 * Take a unit out of service, or put it back.
 *
 * Deliberately NOT part of saveUnitRow: that rewrites the unit's rooms and beds
 * to match what it was handed, which is exactly how the bulk upload detaches
 * residents. Turning a unit off must touch one row and nothing else.
 *
 * A unit with somebody in it is refused. Deactivating hides its beds from
 * placement, so a resident inside one would quietly vanish from Homes - the
 * same rule Release follows: somebody living there is moved, not swept aside.
 */
export const setUnitDeactivated = createServerFn({ method: "POST" })
  .inputValidator((data: { id: string; deactivated: boolean; reason?: string }) => data)
  .handler(async ({ data }) => {
    if (!isUuid(data.id)) return { ok: true as const };
    const supabase = await admin();

    /*
     * What it says now. A unit already out of service keeps the date it went
     * out: editing the reason is a correction to the wording, and re-stamping
     * it as today would destroy the one fact this row exists to hold.
     */
    const { data: current } = await supabase
      .from("units")
      .select("deactivated_at")
      .eq("id", data.id)
      .maybeSingle();
    const alreadyOff = Boolean((current as any)?.deactivated_at);

    // only when turning a LIVE unit off - a unit already off is hidden from
    // placement, so nobody can have moved into it since
    if (data.deactivated && !alreadyOff) {
      // everybody with a claim on it - in it, holding it, or coming to it (placementClaims, 14 Oct 2026)
      const who = [
        ...new Set(
          (await placementClaims(supabase, [data.id]))
            .map((c) => String(c.who || "").trim())
            .filter(Boolean),
        ),
      ];
      if (who.length) {
        return {
          ok: false as const,
          error: `${who.join(", ")} ${who.length === 1 ? "is" : "are"} still in this unit. Move them out before deactivating it.`,
        };
      }
    }

    const { error } = await supabase
      .from("units")
      .update({
        deactivated_at: data.deactivated
          ? ((current as any)?.deactivated_at ?? new Date().toISOString())
          : null,
        // the reason goes with the deactivation and is cleared when it comes back
        deactivation_reason: data.deactivated ? (data.reason ?? "").trim() : "",
      } as any)
      .eq("id", data.id);
    if (error) throw new Error(error.message);
    return { ok: true as const };
  });

/**
 * Work a booking's stage out again after its bed has moved.
 *
 * Placement writes beds directly - it is inventory, not the booking flow - so
 * nothing here recomputed the stage, and a paid student moved to another bed
 * kept whatever stage the move left behind. Reserving one read "Room reserved"
 * on a booking whose fee was already in.
 *
 * The stage is worked out from what is true of the booking now, so this only
 * has to be asked; it is never told what to say.
 */
export const syncStageForBooking = createServerFn({ method: "POST" })
  .inputValidator((data: { enquiryId: string }) => data)
  .handler(async ({ data }) => {
    if (!isUuid(data.enquiryId)) return { ok: true as const };
    const supabase = await admin();
    const { syncBookingStage } = await import("@/lib/booking-lifecycle");
    await syncBookingStage(supabase, data.enquiryId);
    return { ok: true as const };
  });

export const deleteUnitRow = createServerFn({ method: "POST" })
  .inputValidator((data: { id: string }) => data)
  .handler(async ({ data }) => {
    if (!isUuid(data.id)) return { ok: true };
    const supabase = await admin();
    // its rooms and beds go with it, so a unit anybody is placed in - now, later or before - is kept,
    // checked and deleted in one step under the unit's lock (14 Oct 2026)
    const { data: res, error } = await supabase.rpc("delete_unit_if_unused", { p_unit: data.id });
    if (error) throw new Error(rpcError(error));
    if (!(res as any)?.ok)
      throw new Error(String((res as any)?.error ?? "This unit could not be deleted."));
    return { ok: true };
  });

/**
 * Homes Release on a bed held by hand, with nobody and no booking behind it
 * (14 Oct 2026) - SQL release_hand_hold, under the unit's lock. A bed somebody
 * is in, or that a booking or resident holds, is never emptied here: a booking
 * is released from its booking, a resident moved or checked out.
 */
export const releaseHandHold = createServerFn({ method: "POST" })
  .inputValidator((data: { bedId: string }) => data)
  .handler(async ({ data }) => {
    if (!isUuid(data.bedId)) return { ok: false as const, error: "That bed no longer exists." };
    const supabase = await admin();
    const { data: res, error } = await supabase.rpc("release_hand_hold", { p_bed: data.bedId });
    if (error) return { ok: false as const, error: rpcError(error) };
    const out = res as { ok: boolean; error?: string; released?: boolean };
    return out?.ok
      ? { ok: true as const, released: !!out.released }
      : { ok: false as const, error: out?.error || "The bed could not be released." };
  });

/**
 * Where every resident is - SQL resident_placements, the one answer (14 Oct
 * 2026). The browser's Residents list, resident page, document pack and Homes
 * Reserve read this; the server's documents read placementForResident, which
 * asks the same function.
 */
export type ResidentPlacement = {
  bedId: string;
  /** seated: the bed's resident (in it, or first assigned) · tenancy: their stay's bed, to come or before · hold: their booking's */
  via: "seated" | "tenancy" | "hold";
  enquiryId?: string | undefined;
  start?: string | undefined;
  end?: string | undefined;
  /** a room held for their Update Tenancy change */
  next?: { bedId: string; start?: string | undefined; end?: string | undefined } | undefined;
};

export function toPlacement(row: any): ResidentPlacement {
  return {
    bedId: String(row.bed_id),
    via: row.via,
    enquiryId: row.enquiry_id ?? undefined,
    start: row.starts ?? undefined,
    end: row.ends ?? undefined,
    next: row.next_bed_id
      ? {
          bedId: String(row.next_bed_id),
          start: row.next_start ?? undefined,
          end: row.next_end ?? undefined,
        }
      : undefined,
  };
}

export const listResidentPlacements = createServerFn({ method: "GET" }).handler(
  async (): Promise<Record<string, ResidentPlacement>> => {
    const supabase = await admin();
    const { data, error } = await supabase.rpc("resident_placements", { p_residents: null });
    if (error) throw new Error(rpcError(error));
    return Object.fromEntries(
      ((data ?? []) as any[]).map((r) => [String(r.resident_id), toPlacement(r)]),
    );
  },
);

/* ---------------- import batches ---------------- */

export const createImportBatch = createServerFn({ method: "POST" })
  .inputValidator((data: { kind: string; filename?: string; rowCount?: number }) => data)
  .handler(async ({ data }) => {
    const supabase = await admin();
    const { data: row, error } = await supabase
      .from("import_batches")
      .insert({
        kind: data.kind,
        filename: data.filename ?? "",
        row_count: data.rowCount ?? 0,
      } as any)
      .select("id")
      .single();
    if (error) throw new Error(error.message);
    return { id: (row as any).id as string };
  });

/* ---------------- placement: one transaction each, in the database ---------------- */

const notMigrated = (error: { message: string }) =>
  /function .* does not exist|Could not find the function/i.test(error.message);

/** What a placement function says when the database has not had its migration yet. */
function rpcError(error: { message: string }) {
  return notMigrated(error)
    ? "The database needs the placement update (20261014100000_one_placement.sql) before rooms can be reserved this way."
    : error.message;
}

/**
 * Reserve a bed for a booking or a resident, or move them (9 Oct 2026). Every
 * route that places somebody - the booking's room picker, Homes -> Reserve -
 * comes here. The database checks every date, gender and capacity rule again
 * after locking the units involved, so a second admin taking the same room is
 * refused rather than written over - and success is only said once the write
 * is in.
 */
export const placeStay = createServerFn({ method: "POST" })
  .inputValidator(
    (data: { enquiryId?: string; residentId?: string; bedId: string; whole?: boolean; holdUntil?: string }) => data,
  )
  .handler(async ({ data }) => {
    const enquiryId = isUuid(data.enquiryId) ? data.enquiryId! : null;
    const residentId = isUuid(data.residentId) ? data.residentId! : null;
    if ((!enquiryId && !residentId) || !isUuid(data.bedId)) return { ok: false as const, error: "Choose a room first.", detail: "" };
    const supabase = await admin();
    const { data: res, error } = await supabase.rpc("place_stay", {
      p_enquiry: enquiryId,
      p_resident: residentId,
      p_bed: data.bedId,
      p_whole: !!data.whole,
      p_hold_until: data.holdUntil || null,
    });
    if (error) return { ok: false as const, error: rpcError(error), detail: "" };
    const out = res as { ok: boolean; error?: string; detail?: string; placed?: "now" | "later" };
    if (!out?.ok) return { ok: false as const, error: out?.error || "The room could not be reserved.", detail: out?.detail ?? "" };
    if (enquiryId) {
      const { syncBookingStage } = await import("@/lib/booking-lifecycle");
      await syncBookingStage(supabase, enquiryId);
    }
    return { ok: true as const, placed: out.placed ?? "now" };
  });

/**
 * A checked-out resident leaves their bed: whoever has it next becomes its
 * resident, Booked until they arrive; otherwise it is emptied. Their tenancy
 * keeps the bed, so their statement still says where they lived.
 */
export const releaseAfterCheckout = createServerFn({ method: "POST" })
  .inputValidator((data: { residentId: string }) => data)
  .handler(async ({ data }) => {
    if (!isUuid(data.residentId)) return { ok: true as const, promoted: [] as string[] };
    const supabase = await admin();
    const { data: res, error } = await supabase.rpc("release_after_checkout", { p_resident: data.residentId });
    if (error && notMigrated(error)) {
      // before the migration: emptied as it always was - nobody can be booked next yet
      const { error: e2 } = await supabase
        .from("beds")
        .update({
          status: "vacant", resident_id: null, resident_name: null, student_id: null, university: null,
          nationality: null, gender: null, hold_for: null, hold_until: null, enquiry_id: null,
          tenancy_start: null, tenancy_end: null, rent: null,
        })
        .eq("resident_id", data.residentId);
      if (e2) throw new Error(e2.message);
      return { ok: true as const, promoted: [] as string[] };
    }
    if (error) throw new Error(rpcError(error));
    const beds = ((res as any)?.beds ?? []) as { next: string | null }[];
    return { ok: true as const, promoted: beds.map((b) => b.next).filter(Boolean) as string[] };
  });

/** The assigned resident has arrived: their bed goes Booked -> Active. Never by date alone. */
export async function activateAtCheckIn(supabase: any, residentId: string) {
  const { data: res, error } = await supabase.rpc("activate_at_checkin", { p_resident: residentId });
  if (error && notMigrated(error)) {
    // before the migration: the bed they are on goes Active, as it always did
    const { error: e2 } = await supabase
      .from("beds")
      .update({ status: "active", hold_for: null, hold_until: null })
      .eq("resident_id", residentId)
      .in("status", ["held", "booked"]);
    return e2 ? { ok: false as const, error: e2.message } : { ok: true as const };
  }
  if (error) return { ok: false as const, error: rpcError(error) };
  const out = res as { ok: boolean; error?: string };
  return out?.ok ? { ok: true as const } : { ok: false as const, error: out?.error || "Check-in could not be recorded." };
}

export const activateResidentBed = createServerFn({ method: "POST" })
  .inputValidator((data: { residentId: string }) => data)
  .handler(async ({ data }) => {
    if (!isUuid(data.residentId)) return { ok: false as const, error: "Resident not found." };
    return activateAtCheckIn(await admin(), data.residentId);
  });
